function matchesSources013(parts,slots){
 if(!Array.isArray(parts)||parts.length<2)return false;
 if(slots[0]&&parts[0]!==slots[0]||slots[5]&&parts.at(-1)!==slots[5])return false;
 const middle=parts.slice(1,-1);
 for(let i=1;i<5;i++){if(!slots[i])continue;if(i>=parts.length-1)return false;const j=middle.indexOf(slots[i]);if(j<0)return false;middle.splice(j,1);}
 return true;
}
function recipeSlots013(parts){return [parts[0],...Array.from({length:4},(_,i)=>parts.slice(1,-1)[i]||''),parts.at(-1)];}
function filterRecipes(){const q=$('#q').value.toLocaleLowerCase('it'),t=$('#rt').value,l=$('#rl').value,s=$('#rs').value,d=$('#rd').value;
 const fields=[...document.querySelectorAll('.source-filter')];const fixed=TYPES[t];
 const length={BASE:4,MEDIO:5,AVANZATO:6}[l];
 fields.forEach((e,i)=>{const old=e.dataset.fixed&&!fixed?'':e.value;const endpoint=fixed&&(i===0||i===5)?fixed[i===0?0:1]:null;const disabled=!!length&&i>0&&i<5&&i>=length-1;
 e.innerHTML=endpoint?`<option value="${endpoint}">${endpoint}</option>`:`<option value="">Qualsiasi</option>${opts(old)}`;e.dataset.fixed=endpoint||'';e.disabled=disabled||!!endpoint;e.value=disabled?'':endpoint||old;e.parentElement.querySelector('span').textContent=i===5?(length?`Ing. ${length}° · ultimo`:'Ing. ultimo'): `Ing. ${i+1}° passaggio`;});
 const seq=fields.map(e=>e.value);
 const rows=RECIPES.filter(r=>matchesSources013(r.parts,seq)&&(!t||r.type===t)&&(!l||r.level===l)&&(!s||r.school===s)&&(!d||(d==='theory'?recipeTheory(r):d==='yes'?(r.discovered&&!recipeTheory(r)):(!r.discovered&&!recipeTheory(r))))&&(!onlyFav120.recipes||isFav120("recipes",r))&&(!q||(r.name+' '+r.effect+' '+r.extra+' '+r.parts.join(' ')+' '+r.school).toLocaleLowerCase('it').includes(q)));
 $('#list').innerHTML=`<p class="counter">${rows.length} ricette</p>`+rows.map(r=>`<details class="recipe" data-recipe-id="${esc(r.id)}"><summary><div class="line"><span class="name">${esc(r.discovered?r.name:advanced120?'DA PROVARE · #'+r.id:'DA PROVARE')}</span>${statusBadge(r)}${favButton120("recipes",r)}</div><div class="muted">${esc(r.type)} · ${esc(r.level)} · ${esc(r.school||'Scuola non indicata')}</div><span class="technical120">${dots(r.parts)}</span></summary><div class="detail-block"><p><b>Effetto:</b> ${esc(r.effect||'Non ancora conosciuto')}</p>${r.extra?`<p><b>Effetto supplementare / note:</b> ${esc(r.extra)}</p>`:''}<div class="recipeQuick120" data-quick120="${Number(r.id)}"></div><button class="primary action120" onclick="ingredientLists11(${Number(r.id)},false)">${svg120("list")} Ingredienti necessari</button><button class="action120" onclick="shoppingAdd120(${Number(r.id)},false)">${svg120("basket")} Aggiungi alla lista della spesa</button><details class="creation120" ${advanced120?"open":""}><summary>Dettagli di creazione</summary><b>Fonti</b><ol class="ingredient-list">${r.parts.map((p,i)=>`<li>${esc(p)}${i===r.parts.length-1?' · Chiusura, Gen. 1':''}</li>`).join('')}</ol>${dots(r.parts)}<p class="adminOnly120 muted">Riga ${r.id} del foglio Ricette.</p></details>${editLink012("recipes",r.id)}</div></details>`).join('')}
