function calc(){main.innerHTML=`<section class="screen"><h1 class="h">Ruota del Creazionismo</h1><p class="technical120 muted">Configura le Fonti e consulta i percorsi.</p><div class="panel"><div class="filters"><select id="size"><option value="BASE">Base · 4 passaggi</option><option value="MEDIO">Media · 5 passaggi</option><option value="AVANZATO">Avanzata · 6 passaggi</option></select><select id="type">${Object.keys(TYPES).map(s=>`<option value="${s}">${s}</option>`).join('')}</select></div><div id="steps"></div></div><div id="results"></div></section>`;$('#size').value=size;$('#type').value=type;$('#size').onchange=e=>{size=e.target.value;resetParts();steps()};$('#type').onchange=e=>{type=e.target.value;resetParts();steps()};steps()}
function steps(){const fixed=TYPES[type]||TYPES.POZIONE;parts[0]=fixed[0];parts[parts.length-1]=fixed[1];$('#steps').innerHTML=parts.map((s,i)=>`<div class="step"><label>${i===0?'Apertura':i===parts.length-1?'Chiusura':'Passaggio '+(i+1)}</label><select data-i="${i}" ${i===0||i===parts.length-1?'disabled':''}>${opts(s)}</select><span class="dot" style="background:${COLORS[s]}">${SHORT[s]}</span></div>`).join('')+`<p class="muted">Apertura: ${parts[0]}. Chiusura: ${parts.at(-1)}, Gen. 1. Entrambe fisse.</p>`;document.querySelectorAll('#steps select:not(:disabled)').forEach(el=>el.onchange=e=>{parts[+e.target.dataset.i]=e.target.value;steps()});results()}
// Ruota: trascrizione esatta delle 15 posizioni per generazione dal foglio "Ruota".
const WHEEL_ROWS=[
['—','EQ','—','EN','FO','CA','MA','SP','—','EQ','MA','EN','CA','SP','FO'],
['EN','—','FO','EQ','SP','—','FO','MA','EQ','CA','—','EN','SP','CA','MA'],
['CA','FO','—','MA','EN','—','EQ','SP','EQ','SP','MA','—','CA','FO','EN'],
['MA','—','EN','—','CA','EQ','—','EN','MA','FO','CA','EQ','SP','SP','FO']
];
const GENPATHS={BASE:[[4,3,2,1],[2,3,2,1],[2,1,2,1]],MEDIO:[[1,2,1,2,1],[1,2,3,2,1],[3,2,1,2,1],[3,2,3,2,1],[3,4,3,2,1]],AVANZATO:[[2,1,2,1,2,1],[2,1,2,3,2,1],[2,3,2,1,2,1],[2,3,2,3,2,1],[2,3,4,3,2,1],[4,3,2,1,2,1],[4,3,2,3,2,1],[4,3,4,3,2,1]]};
const PER_STEP={1:3,2:6,3:9,4:12};
function permutations(a){if(a.length<2)return[a];return a.flatMap((x,i)=>permutations(a.filter((_,j)=>j!==i)).map(p=>[x,...p]))}
function scanTo(source,gen,from){const row=WHEEL_ROWS[gen-1];let first=-1,second=-1;
  for(let step=1;step<=30;step++){
    let pos=from===0?((step-1)%15):((from+step-1)%15);
    if(row[pos]===SHORT[source]){if(first<0)first=step;else{second=step;break}}
  }
  if(first<0||second<0)return null;
  return [first,second];
}
function candidate(seq,gens,choices){let pos=0,total=0,works=0,steps=[];
  for(let i=0;i<seq.length;i++){
    const g=gens[i],find=scanTo(seq[i],g,pos);if(!find)return null;
    const w=find[choices[i]-1];if(w<1||w>15)return null;
    pos=(pos+w-1)%15+1;
    const qty=Math.ceil(w/PER_STEP[g]);total+=qty;works+=w;
    steps.push({source:seq[i],gen:g,work:w,qty,arrival:pos,choice:choices[i]});
  }
  return {total,works,steps,gens,seq};
}
function computeTop10(sources,level){const gensList=GENPATHS[level],centers=sources.slice(1,-1),orders=permutations(centers.map((_,i)=>i));
 const best=[];let count=0;
 for(const gens of gensList)for(const order of orders){const seq=[sources[0],...order.map(i=>centers[i]),sources.at(-1)];
   for(let mask=0;mask<(1<<seq.length);mask++){
     const choices=seq.map((_,i)=>((mask>>i)&1)+1),c=candidate(seq,gens,choices);
     if(!c)continue;count++;best.push(c);
   }
 }
 best.sort((a,b)=>a.total-b.total||a.works-b.works||a.gens.join('').localeCompare(b.gens.join('')));
 return {best:best.slice(0,10),count};
}
function results(){
 const exact=RECIPES.filter(r=>r.level===size&&r.type===type&&r.parts.length===parts.length&&matchesSources013(r.parts,recipeSlots013(parts)));
 const recognized=exact.filter(r=>r.discovered);
 const theoryMatch=recognized.find(recipeTheory);
 const art=['RUNA','PERGAMENA','GRIMORIO'].includes(type);
 const {best,count}=computeTop10(parts,size);
 const minQty=best.length?best[0].total:null;
 const sameMin=best.filter(x=>x.total===minQty);
 const priced=sameMin.map(c=>({c,p:priceEstimate(c,'buy')})).filter(x=>x.p!==null).sort((a,b)=>a.p.sum-b.p.sum);
 const priceNote=priced.length===sameMin.length&&sameMin.length?`<p class="notice">★ Minimo ingredienti: ${minQty}. ★ Stima a prezzo unitario tra le 10 soluzioni, a parità di ingredienti: ${priced[0].p.sum.toLocaleString('it-IT')} (usando il prezzo più basso per ogni Fonte/Generazione). Non include l’arrotondamento delle confezioni; per il costo effettivo usa le proposte ingredienti.</p>`:`<p class="notice">★ Percorso più efficiente: ${minQty??'—'} ingredienti. ★ Percorso più economico: non ancora determinabile, mancano i prezzi di acquisto per tutte le Fonti/Generazioni necessarie. Il confronto sarà attivo appena i dati saranno completi.</p>`;
 $('#results').innerHTML=`<h2 class="h">Le 10 soluzioni con meno ingredienti</h2><div class="panel"><div class="line"><b>${recognized.length===1?esc(recognized[0].name):exact.length>1?'Più ricette corrispondenti':exact.length?'DA PROVARE':'Opera non identificata'}</b>${theoryMatch?'<span class="badge theory">TEORIA</span>':recognized.length?'<span class="badge">Scoperta</span>':'<span class="badge unknown">Sconosciuta</span>'}</div><p class="muted">${recognized.length===1?esc(recognized[0].effect):'Consulta le ricette corrispondenti qui sotto.'}</p>${exact.length?exact.map(r=>`<div class="detail-block calc-match101"><b>${esc(r.name)} · #${esc(r.id)}</b><button class="recipe-exit133" onclick="openRecipe013(${Number(r.id)})">Apri ricetta</button>${editLink012("recipes",r.id)}</div>`).join(''):'<p class="muted">Nessuna combinazione corrispondente nell’archivio.</p>'}${art?'<p class="warning">Artimagia: validità del sistema ancora da verificare.</p>':''}<p class="muted">Le Fonti centrali possono essere riordinate. La chiusura è sempre in generazione 1.</p></div>
 <p class="technical120 muted">${count} percorsi calcolabili · ordinati per quantità di ingredienti, poi per numero totale di lavorazioni. Conteggi ricavati dalle tabelle «Ruota» e «Regole» di Brumo; da confrontare con i risultati del foglio originale.</p>
 ${advanced120?priceNote:""}${best.length?best.map((c,i)=>`<details class="recipe"><summary><div class="result-heading"><span class="name">${i+1}. Soluzione</span><span class="tag">${c.total} ingredienti · ${c.works} lavorazioni</span></div><div class="muted">Gen. ${c.gens.join(' → ')}</div>${dots(c.seq)}</summary><div class="calc-stats"><div><strong>${c.total}</strong><small>Ingredienti totali</small></div><div><strong>${c.works}</strong><small>Lavorazioni totali</small></div></div><div class="work-list">${c.steps.map((s,j)=>`<div><b>${j+1}= ${esc(s.source)} • Gen. ${s.gen}</b><p>${s.qty} Ingredienti × ${s.work} Lavorazioni</p><small>Pallino ${s.arrival} · ${s.choice}° occorrenza</small></div>`).join('')}</div>${digitalWheel(c,i)}</details>`).join(''):'<div class="notice">Nessun percorso calcolabile con le regole attuali. Questo non dimostra che l’opera sia impossibile.</div>'}
 <p class="muted">Calcoli da verificare secondo le regole di gioco.</p>`;
}
