function ingredientChip(name){const v=ING_BY_NAME.get(String(name).toLocaleLowerCase('it'));const src=v?.source||'';if(/^alium$/i.test(name))return '<span class="ingredient-chip" style="--source:#d4b6e5"><span class="source-mark">AL</span> Alium · Fonte/Gen. non indicate</span>';return `<span class="ingredient-chip" style="--source:${COLORS[src]||'#657a87'}"><span class="source-mark">${src?SHORT[src]:'??'}</span> ${esc(name)} ${v?.gen?'· G'+v.gen:''}</span>`}
