// 1.1.1 — proposals: use all valid wheel paths and actual market unit purchase prices.
function proposalIngredients111(r,inventory=INGREDIENTS){
 const paths=GENPATHS[r.level];if(!paths||!Array.isArray(r.parts)||r.parts.length!==paths[0].length)return {lists:[],priced:false};
 const pools=new Map();for(const x of inventory){if(!x.name||!COLORS[x.source]||!PER_STEP[Number(x.gen)])continue;const key=x.source+'|'+Number(x.gen);if(!pools.has(key))pools.set(key,[]);pools.get(key).push({name:x.name,sa:x.alium===true,pack:parsePack120(x.buy)});}
 const needed=new Set(),orders=[...new Map(permutations(r.parts.slice(1,-1)).map(o=>[JSON.stringify(o),o])).values()];const candidates=[];
 for(const gens of paths)for(const order of orders){const seq=[r.parts[0],...order,r.parts.at(-1)];for(let mask=0;mask<(1<<seq.length);mask++){const c=candidate(seq,gens,seq.map((_,i)=>((mask>>i)&1)+1));if(!c)continue;const keys=c.steps.map(s=>s.source+'|'+s.gen);if(keys.some(k=>!pools.has(k)))continue;candidates.push({c,keys});keys.forEach(k=>needed.add(k));}}
 const priced=needed.size>0&&[...needed].every(k=>pools.get(k).every(x=>x.pack!==null));
 const top=[],cmp=(a,b)=>a.sa-b.sa||(priced?a.cost-b.cost:0)||a.qty-b.qty||a.works-b.works||a.key.localeCompare(b.key,'it');
 function keep(arr,v){const j=arr.findIndex(x=>x.key===v.key);if(j>=0){if(cmp(v,arr[j])>=0)return;arr.splice(j,1)}arr.push(v);arr.sort(cmp);if(arr.length>2)arr.pop();}
 function rank(entries){let sa=0,cost=0,qty=0,works=0;const counts=new Map();for(const e of entries){const [name,q,w,s,p]=e;sa+=s?q:0;qty+=q;works+=w;const count=counts.get(name)||{q:0,p};count.q+=q;counts.set(name,count)}if(priced)for(const {q,p} of counts.values())cost+=Math.ceil(q/p.units)*p.price;return {entries:entries.map(e=>e.slice(0,4)),sa,cost:priced?cost:null,qty,works,key:JSON.stringify([...counts.keys()].sort((a,b)=>a.localeCompare(b,'it')))};}
 for(const {c,keys} of candidates){const groups=new Map();keys.forEach((k,i)=>{if(!groups.has(k))groups.set(k,[]);groups.get(k).push(i)});const variants=[];for(const [k,indices] of groups){const options=[],entries=[];function visit(n){if(n===indices.length){const v=rank(entries);v.raw=entries.map(x=>x.slice());keep(options,v);return}const s=c.steps[indices[n]];for(const x of pools.get(k)){entries.push([x.name,s.qty,s.work,x.sa,x.pack]);visit(n+1);entries.pop()}}visit(0);variants.push({indices,options})}function combine(alt){const selected=[];variants.forEach(({indices,options},i)=>{const v=options[alt===i?1:0];indices.forEach((index,n)=>selected[index]=v.raw[n])});keep(top,rank(selected))}combine(-1);for(let i=0;i<variants.length;i++)if(variants[i].options.length>1)combine(i);}
 return {lists:top,priced};
}
