async function copy120(text,button){try{await navigator.clipboard.writeText(text);button.textContent='Copiato'}catch{const el=document.createElement('textarea');el.value=text;el.readOnly=true;button.after(el);el.select();button.textContent='Copia il testo selezionato'}}
function shoppingOpen120(){if(document.querySelector('dialog.shopping120[open]'))return;const d=dialog120('Lista della spesa','shopping120'),body=document.createElement('div');d.append(body);function draw(){body.replaceChildren();const total=local120.shopping.reduce((n,r)=>n+r.qty,0);const info=document.createElement('p');info.textContent=total?total+(total===1?' opera selezionata':' opere selezionate'):'La lista è vuota. Aggiungi una proposta da una ricetta.';body.append(info);if(!total)return;const ops=document.createElement('details');ops.className='panel';const sum=document.createElement('summary');sum.textContent='Opere selezionate';ops.append(sum);for(const r of local120.shopping){const line=document.createElement('div');line.className='shopLine120';const t=document.createElement('span');t.textContent=r.name+' · '+(r.alium?'Alium':'Proposta '+r.proposal);const live=(r.alium?ALIUM:RECIPES).some(x=>favKey120(r.alium?'alium':'recipes',x)===r.recipeKey);if(!live){const s=document.createElement('small');s.textContent='Ricetta modificata o non più presente: verifica la lista.';t.append(s)}const qty=document.createElement('input');qty.type='number';qty.min=1;qty.max=999;qty.value=r.qty;qty.setAttribute('aria-label','Quantità '+r.name);qty.onchange=()=>{r.qty=Math.max(1,Math.min(999,Math.floor(Number(qty.value)||1)));saveLocal120();draw();ops.open=true};const rem=document.createElement('button');rem.className='ingredientClose111';rem.innerHTML=svg120('x');rem.setAttribute('aria-label','Rimuovi '+r.name);rem.onclick=()=>{local120.shopping=local120.shopping.filter(x=>x!==r);saveLocal120();draw()};line.append(t,qty,rem);ops.append(line)}body.append(ops);const counts=shoppingData120();const missing=[];for(const [name,q] of counts){const owned=Math.min(q,Math.max(0,Number(local120.owned[name])||0));const row=document.createElement('label');row.className='shopLine120'+(owned===q?' checked':'');const ck=document.createElement('input');ck.type='checkbox';ck.checked=owned===q;ck.onchange=()=>{local120.owned[name]=ck.checked?q:0;saveLocal120();draw()};const n=document.createElement('span');n.textContent=name+(INGREDIENTS.find(i=>i.name===name)?.alium?' [S.A.]':'');if(owned>0&&owned<q){const s=document.createElement('small');s.textContent=owned+' già posseduti · '+(q-owned)+' da procurare';n.append(s)}const amount=document.createElement('strong');amount.textContent='× '+q;row.append(ck,n,amount);body.append(row);if(q>owned)missing.push([name,q-owned])}const totals=document.createElement('div');totals.className='panel';const q=quote120(missing),m=quote120(missing,true);totals.textContent='Costo da procurare: '+money120(q);if(m!==null&&m!==q){const s=document.createElement('p');s.textContent='Con offerte mercante (se accessibili): '+money120(m);totals.append(s)}body.append(totals);const cp=document.createElement('button');cp.className='action120';cp.innerHTML=svg120('copy')+' Copia lista da procurare';cp.onclick=()=>copy120(missing.map(([n,q])=>q+' × '+n+(INGREDIENTS.find(i=>i.name===n)?.alium?' [S.A.]':'')).join('\n')||'Nessun ingrediente mancante',cp);const clear=document.createElement('button');clear.className='action120';clear.textContent='Svuota lista';clear.onclick=()=>{if(confirm('Svuotare la lista della spesa?')){local120.shopping=[];local120.owned={};saveLocal120();draw()}};body.append(cp,clear)}draw();d.showModal()}
function possibleIngredient120(r,x){const g=Number(x.gen),paths=GENPATHS[r.level];if(!paths||!r.parts?.includes(x.source)||!PER_STEP[g])return false;const orders=[...new Map(permutations(r.parts.slice(1,-1)).map(o=>[JSON.stringify(o),o])).values()];for(const gens of paths){if(!gens.includes(g))continue;for(const order of orders){const seq=[r.parts[0],...order,r.parts.at(-1)];if(!seq.some((s,i)=>s===x.source&&gens[i]===g))continue;for(let mask=0;mask<(1<<seq.length);mask++)if(candidate(seq,gens,seq.map((_,i)=>((mask>>i)&1)+1)))return true}}return false}
function revealRecipe120(r,alium){onlyFav120[alium?'alium':'recipes']=false;recipeMode=alium?'alium':'traditional';switchTab('recipes');if(alium){$('#aq').value=r.name||r.ingredients[0]||'';filterAlium();const el=document.querySelector(`#alist details[data-alium-id="${Number(r.id)}"]`);if(el){el.open=true;el.scrollIntoView({block:'start'})}}else{$('#q').value=r.discovered?r.name:'';filterRecipes();const el=document.querySelector(`#list details[data-recipe-id="${Number(r.id)}"]`);if(el){el.open=true;el.scrollIntoView({block:'start'})}}}
async function reverseOpen120(name){const x=INGREDIENTS.find(i=>i.name===name);if(!x)return;const d=dialog120(name,'reverse120');const status=document.createElement('p');status.textContent='Ricerca delle opere compatibili…';const list=document.createElement('div');list.className='reverseList120';d.append(status,list);d.showModal();let n=0;const append=(r,alium)=>{n++;const b=document.createElement('button');b.className='action120';b.textContent=(r.name||'Combinazione senza nome')+' · '+(alium?'Alium: componente esatto':r.type+' · '+r.level+' · compatibile');b.onclick=()=>{d.close();revealRecipe120(r,alium)};list.append(b)};for(const r of ALIUM)if(r.ingredients?.includes(name))append(r,true);const rows=RECIPES.filter(r=>r.discovered&&r.parts?.includes(x.source));for(let i=0;i<rows.length;i++){if(!d.open||!d.isConnected)return;if(possibleIngredient120(rows[i],x))append(rows[i],false);if(i%20===19)await new Promise(resolve=>setTimeout(resolve,0))}status.textContent=n?n+' opere trovate. Compatibilità tradizionale non significa ingrediente obbligatorio.':'Nessuna opera nota compatibile.'}
